local GardenForkMaker = {}
local PRODUCTS = {
    iron_gardenfork = { name = "Železni vrtne vilice", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vrtne vilice za vrtnarje." },
    bronze_gardenfork = { name = "Bronast vrtne vilice", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vrtne vilice za vrtnarje." },
    silver_gardenfork = { name = "Srebrn vrtne vilice", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vrtne vilice za vrtnarje." },
    gilded_gardenfork = { name = "Pozlačen vrtne vilice", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vrtne vilice za vrtnarje." },
    jewel_set_gardenfork = { name = "Draguljast vrtne vilice", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vrtne vilice za vrtnarje." },
    royal_sovereign_gardenfork = { name = "Kraljevski suveren vrtne vilice", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vrtne vilice z biseri za krono." },
}
local BUILDINGS = {
    gardenfork_workshop = { name = "Gardenfork delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardenfork_house = { name = "Gardenfork hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardenfork_atelier = { name = "Mojstrski gardenfork atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardenfork_palace = { name = "Suverena gardenfork palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenForkMaker.ironStock=18; GardenForkMaker.bronzeStock=14; GardenForkMaker.woodStock=10; GardenForkMaker.leatherStock=8; GardenForkMaker.silverStock=8; GardenForkMaker.goldStock=6; GardenForkMaker.jewelStock=4; GardenForkMaker.pearlStock=4
GardenForkMaker.productStock = {}; GardenForkMaker.buildings = {}; GardenForkMaker.maker = nil; GardenForkMaker.activeMaking = {}; GardenForkMaker.totalProducts = 0; GardenForkMaker.dayTimer = 0
function GardenForkMaker.init() GardenForkMaker.ironStock=18; GardenForkMaker.bronzeStock=14; GardenForkMaker.woodStock=10; GardenForkMaker.leatherStock=8; GardenForkMaker.silverStock=8; GardenForkMaker.goldStock=6; GardenForkMaker.jewelStock=4; GardenForkMaker.pearlStock=4; GardenForkMaker.productStock={}; GardenForkMaker.buildings={}; GardenForkMaker.maker=nil; GardenForkMaker.activeMaking={}; GardenForkMaker.totalProducts=0; GardenForkMaker.dayTimer=0; print("[GardenForkMaker] Royal Garden Fork Maker System initialized (6 products, 4 buildings)") end
function GardenForkMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenForkMaker.maker={name=n or ("Viliar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Viliar najet: %s (spretnost: %d)",GardenForkMaker.maker.name,s),"success") end; return true end
function GardenForkMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenForkMaker.build(id) local ok,e=GardenForkMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenForkMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenForkMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenForkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenForkMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenForkMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenForkMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenForkMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenForkMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenForkMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenForkMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenForkMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenForkMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenForkMaker.buildings==0 then return false,"Potrebna vilična delavnica" end; if not GardenForkMaker.maker then return false,"Potreben viliar" end; return true end
function GardenForkMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenForkMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenForkMaker.ironStock=GardenForkMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenForkMaker.bronzeStock=GardenForkMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenForkMaker.woodStock=GardenForkMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenForkMaker.leatherStock=GardenForkMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenForkMaker.silverStock=GardenForkMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenForkMaker.goldStock=GardenForkMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenForkMaker.jewelStock=GardenForkMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenForkMaker.pearlStock=GardenForkMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenForkMaker.maker then t=math.max(1,t-math.floor(GardenForkMaker.maker.skill/13)) end; table.insert(GardenForkMaker.activeMaking,{id="gardenfork_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenForkMaker.completeMaking(m) local q=1.0+(GardenForkMaker.getQualityBonus()/100); if GardenForkMaker.maker then q=q+(GardenForkMaker.maker.skill/140) end; q=math.min(2.5,q); GardenForkMaker.productStock[m.productType]=(GardenForkMaker.productStock[m.productType] or 0)+m.quantity; GardenForkMaker.totalProducts=GardenForkMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenForkMaker.maker then GardenForkMaker.maker.itemsMade=GardenForkMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenForkMaker.maker.skill=math.min(100,GardenForkMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vilice izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenfork.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenForkMaker.update(dt) if not _G.state then return end; GardenForkMaker.dayTimer=GardenForkMaker.dayTimer+dt; if GardenForkMaker.dayTimer>=30 then GardenForkMaker.dayTimer=0; for i=#GardenForkMaker.activeMaking,1,-1 do local m=GardenForkMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenForkMaker.completeMaking(m); table.remove(GardenForkMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenForkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenForkMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenForkMaker.getStats() return {ironStock=GardenForkMaker.ironStock,bronzeStock=GardenForkMaker.bronzeStock,woodStock=GardenForkMaker.woodStock,leatherStock=GardenForkMaker.leatherStock,silverStock=GardenForkMaker.silverStock,goldStock=GardenForkMaker.goldStock,jewelStock=GardenForkMaker.jewelStock,pearlStock=GardenForkMaker.pearlStock,productStock=GardenForkMaker.productStock,numBuildings=#GardenForkMaker.buildings,hasMaker=GardenForkMaker.maker~=nil,makerName=GardenForkMaker.maker and GardenForkMaker.maker.name or "—",makerSkill=GardenForkMaker.maker and GardenForkMaker.maker.skill or 0,activeMaking=#GardenForkMaker.activeMaking,totalProducts=GardenForkMaker.totalProducts} end
return GardenForkMaker
